3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners share this owner's firstName and lastName
9	 * (case-insensitively) at create time, before the new owner is saved.
10	 */
11	public class CountNamesakes {
12	
13	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
14	        String firstName = normalise(owner.getFirstName());
15	        String lastName = normalise(owner.getLastName());
16	        int count = 0;
17	        for (Owner existing : ownerRepository.findAll()) {
18	            if (firstName.equals(normalise(existing.getFirstName()))
19	                    && lastName.equals(normalise(existing.getLastName()))) {
20	                count++;
21	            }
22	        }
23	        owner.setNamesakeCount(count);
24	    }
25	
26	    private static String normalise(String value) {
27	        return value == null ? "" : value.trim().toLowerCase();
28	    }
29	}
